import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <OverlayProvider>
      {children}
      {toast && <Toaster />}
    </OverlayProvider>
  </CSPProvider>
);

export const ShowcaseSurface = ({ children }: { children?: ReactNode }) => (
  <div
    data-slot="component-preview"
    className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
  >
    {children}
  </div>
);

import { useState } from "react";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from "@/registry/erbium/ui/input-group";
import { Icon } from "@/registry/erbium/ui/icon";
import { useCopyToClipboard } from "@/registry/erbium/hooks/use-copy-to-clipboard";

const Demo = () => {
  const [value, setValue] = useState("https://erbium.dev");
  const { copyToClipboard, isPending, reset, revision, status } = useCopyToClipboard();
  const feedback = { copied: "URL copied.", error: "Could not copy the URL.", idle: "" };

  return (
    <div className="grid w-80 max-w-full gap-related">
      <InputGroup>
        <InputGroupInput
          aria-label="URL"
          value={value}
          onChange={(event) => {
            setValue(event.target.value);
            reset();
          }}
        />
        <InputGroupAddon align="inline-end">
          <InputGroupButton
            aria-label="Copy URL"
            focusableWhenDisabled
            loading={isPending}
            onClick={() => {
              void copyToClipboard(value);
            }}
            size="icon-xs"
            variant="embedded"
          >
            <Icon name="copy" />
          </InputGroupButton>
        </InputGroupAddon>
      </InputGroup>
      <output aria-atomic="true" className="min-h-5 text-caption">
        <span key={revision}>{feedback[status]}</span>
      </output>
    </div>
  );
};

export default Demo;

